export const APPROVED_SOURCE_LINK_COUNT=9 as const;
export const universeByType=(type:string)=>APPROVED_UNIVERSE_RECORDS.filter(r=>r.type===type);
export const universeSearch=(query:string)=>{const q=query.trim().toLocaleLowerCase();if(!q)return APPROVED_UNIVERSE_RECORDS.slice(0,24);return APPROVED_UNIVERSE_RECORDS.filter(r=>[r.id,r.titleEn,r.titleTa,r.locator,r.searchText,...r.sourceIds].join(" ").toLocaleLowerCase().includes(q)).slice(0,60)};
export const universeKanda=(locator:string)=>{const m=locator.match(/Kanda[- ]?(\d+)/i);return m?Number(m[1]):null};
export const universeKandaCounts=()=>APPROVED_UNIVERSE_RECORDS.reduce<Record<string,number>>((a,r)=>{const k=universeKanda(r.locator);const key=k?String(k):"unmapped";a[key]=(a[key]||0)+1;return a},{});
